const SET_BONUS_STD="Kein Set-Bonus — Wert nur aus Einzelteil-Stats + Abyss-Cores";
const MISSABLE_ITEMS=[
  {id:'ms1',cat:'Waffe',name:'Sword of the Lord',when:'Kap. 2 — nach Kailok besiegen',tip:'Automatischer Drop von Kailok the Hornsplitter nach Pflichtboss-Sieg — NICHT missable, wird garantiert vergeben.'},
  {id:'ms2',cat:'Waffe',name:'Tauria Curved Sword + Crow\'s Pursuit',when:'Kap. 5 — Draven besiegen (Story)',tip:'BiS Curved Sword bis Endgame. Story-Pflicht, aber Core-Drop aus Loot sicherstellen.'},
  {id:'ms3',cat:'Waffe',name:'Brass Rose Rapier',when:'Silverbrook Ruins (Delesyia, N)',tip:'Audit 02.06.2026 KORREKTUR: doch NICHT missable — frei aufsammelbar (unterste Turm-Ebene), nicht Damiane-exklusiv beim Holen (Fextralife). Kein echter Missable.'},
  {id:'ms4',cat:'Waffe',name:'Hollow Visage (Dawn Cave)',when:'Kap. 3 — Truhe am Ende der Dawn Cave (hinter dem Wasserfall, Mountain of Frozen Souls)',tip:'Versteckte Truhe ohne Map-Marker; der Wasserfall muss per Stab-Stoß durchbrochen werden. questlog führt zusätzlich den Händler Ronan (348 Silber), Fextralife nennt die Waffe nicht kaufbar — daher kein gesichert verpassbarer Fund. Ein „einmaliger Spawn“ ist nicht belegt.'},
  {id:'ms5',cat:'Rüstung',name:'Leather Helm of the Fallen Kingdom',when:'Sanctum of Benediction (Hernand/Pailune)',tip:'Niemals für ein anderes Item tauschen. Momentum-Core (+35% Turning Slash) ist fest eingebaut.'},
  {id:'ms6',cat:'Quest',name:'Hexe Elowen — "The Missing Seal"',when:'Kap. 5 — startet automatisch nach Exposed Plot',tip:'Pflicht-Storyquest (questlog: Quest Black and White), kein Missable: Elowen spricht über den Hexenzirkel und warnt vor einer Macht, die die Hexen ausschalten und ihre Heiligtümer an sich reißen will. Belohnung laut questlog u. a. Gear Blueprint: Haste, Abyss Cell, Sealed Letter. Dass die Quest Tier-3-Core-Synthese oder einen Kuku-Blueprint freischaltet, ist nicht belegt. Elowens Hexenhaus liegt laut LOCATIONS in den Witchwoods (Südwest-Hernand); die Angabe Alfonso Estate stammt von game8 und ist nicht eindeutig: questlog beschreibt das Alfonso Estate als Anwesen im Westen Hernands, Sitz des House Alfonso, und Elowen nur als Hexe der Weisheit mit einem blumenumkränzten Häuschen in Hernand.'},
  {id:'ms7',cat:'Quest',name:'Oongka — Arm Wrestling (optional)',when:'Ab Kap. 8 — Calphade Castle (nach der Angel-Quest)',tip:'"Strength Held in the Fingertips" (Greymanes-Fraktionsquest, Scattered Embers): Oongka erscheint bei Calphade Castle, nachdem die Angel-Quest "Words Left by the Riverside" erledigt ist (PowerPyx). Laut PowerPyx erscheint erst danach der Champion der Armdrück-Challenge Hero\'s Handshake 2. Kein Quellenbeleg für ein Zeitfenster nur in Kap. 8, für Verpassbarkeit, für einen Bezug zu Oongkas Verfügbarkeit oder für Pflicht fürs True Ending; die frühere Aussage "danach dauerhaft gesperrt" ist unbelegt.'},
  {id:'ms8',cat:'Quest',name:'Oongka dauerhaft — Riverside',when:'Kap. 8 — Fluss bei der Beighen Weavery (südlich von Pailune)',tip:'"Words Left by the Riverside" (Greymanes-Fraktionsquest, erscheint zu Beginn von Kap. 8). Zu Oongkas Verfügbarkeit: PowerPyx nennt nur eine zeitweise Sperre nach Time to Face Justice (for a while, ohne Auslöser der Rückkehr); laut game8 wird er erst mit dieser Quest dauerhaft zugänglich; questlog (Quest 1000314, Mission Gentle Sound of Flowing River, Belohnung Fishing Rod) und Fextralife nennen dazu nichts. Als verpassbar ist sie in keiner Quelle gekennzeichnet; als Pflicht fürs True Ending ist sie nicht belegt.'},
  {id:'ms9',cat:'Quest',name:'Lyselia-Questlinie abschließen',when:'Zeitfenster nicht belegt',tip:'Sanctum of Devotion → Veneration → Oblation → Faith (Delesyia); questlog: Quest "The Witch of Humility" mit vier Sanctum-Missionen. Die frühere Frist (vor Ende von Kap. 10 abschließen) ist in keiner geprüften Quelle belegt; laut ConsolePulse gibt es unter Patch 1.16 keine bestätigt dauerhaft verpassbaren Trophäen. Für die Lightbringer-Trophy zählen ohnehin alle 16 Sanctums.'},
  {id:'ms10',cat:'Mount',name:'Snowwhite Deer fangen',when:'Pailune — Silver Wolf Mountain',tip:'Tier flieht sofort. Aerial Force Palm + Sleep/Poison Arrows. Einziger Spawn — Camp-Rest bei Fehler.'},
  {id:'ms11',cat:'Mount',name:'Icicle Edge Alpine Ibex',when:'Quest "The Sport Hunter" — Wayward Woods',tip:'Boss Moren der Mistwood Huntmaster. 2 Phasen. Feuer bricht Mount-Bindung.'},
  {id:'ms12',cat:'Mount',name:'Rock Tusk Warthog',when:'Quest "Master of the Wetlands" — Bordig Ruins',tip:'Nur über Faction-Quest zugänglich. Ravok of the Savage Fangs, 2 Phasen.'},
  {id:'ms13',cat:'Quest',name:'Greymane Commissions',when:'Kap. 3–12 — fortlaufend abschließen',tip:'Korrektur 22.08.2026: NICHT Pflicht fürs True Ending. Keine geprüfte Quelle verknüpft die Commissions mit dem Ende; Vollständigkeit zählt nur für die kumulativen Inventarplätze. Freischaltung: Die 27 Requests liegen im Journal unter Faction Quests > Greymanes > Tales of the Greymanes; eine Request erscheint erst, wenn der jeweilige Greymane rekrutiert ist (ConsolePulse). Camp-Umzug nach Pailune: Laut einem Spielerkommentar (PowerPyx Trophy Guide, Einzelquelle) werden dabei NPCs durch Greymane-Mitglieder ersetzt und eine offene Pailune-Request wird als gescheitert markiert (siehe Eintrag Pailune-Händler-Requests); für die 27 Greymane Commissions im Camp selbst ist kein Fehlschlagen belegt.'},
  {id:'ms14',cat:'True Ending',name:'Axiom Archive Records lesen',when:'Nach Freischalten — The Abyss (3. Stock)',tip:'Audit 02.06.2026: 6 Archive-Record-Bücher im Axiom ARCHIVE (nicht 3, nicht "Library"); werden NACH dem Freischalten gelesen (Lore), sind NICHT das Gate. True-Ending-Gate = alle Hauptquests + alle 40 Abyss-Challenges (vulkk/PowerPyx).'},
  {id:'ms15',cat:'True Ending',name:'SAVE vor dem Tor zu Corrupted Caliburn',when:'Kap. 12 — Mission "A Shadow in the Void", Dimensional Bonds (vor dem Tor zu Corrupted Caliburn)',tip:'Manuell speichern, bevor du das Tor zu Corrupted Caliburn betrittst, und vorher Vorräte auffüllen. Wer im Kampf gegen Myurdin "Give Up" wählt oder das Spiel beendet, wird weit entfernt abgesetzt und kann das Tor nicht erneut betreten; dann hilft nur der Save (Corrupted Caliburn erneut besiegen, PowerPyx). Stirbst du im Kampf gegen Umbra, muss Myurdin laut PowerPyx nicht erneut besiegt werden; die Lebensleiste des Bosses regeneriert sich nicht. Die Warnung vor "Give Up" und vor dem Beenden des Spiels steht bei PowerPyx in der Mission "Blinding Darkness", der Hinweis zum Beenden nach dem ersten Boss in "A Shadow in the Void".'},
  {id:'ms16',cat:'Waffe',name:'Vessel of Dark Pursuit',when:'Sanctum of Absolution (Hernand) — Boss Antumbra\'s Sword; Special-Weapon-Challenge 10',tip:'Einmaliger Sanctum-Drop. Laut PowerPyx gibt es pro Durchgang nur ein Exemplar: nicht verkaufen oder wegwerfen (Challenge „100 Gegner besiegen“, Trophy Grand Collector of Arms); ein verlorenes Exemplar sei nicht ersetzbar. Widerspruch: questlog führt Elowen als Händlerin (Preisfeld 2289), und laut ConsolePulse bieten Händler seit Patch 1.11 zuvor erhaltene Rare-Equipment-Stücke wieder an (bis zu sieben Ingame-Tage, teurer). Ob die Vessel zurückkaufbar ist, ist ingame ungeprüft — sicherheitshalber behalten.'},
  {id:'ms17',cat:'Rüstung',name:'Marni Laser Helm',when:'Special-Weapon-Challenge 8 — vor dem Kuku-Umbau abschließen',tip:'Laut PowerPyx pro Durchgang nur ein Exemplar; für die Challenge (5 Gegner mit einem Laserstrahl treffen) zählt nur die Basisversion, die Kuku-Version nicht. Das questlog-Rezept für den Kuku Marni Laser Helm verbraucht 1x Marni Laser Helm: erst die Challenge abschließen, dann umbauen.'},
];
const FUNDORTE={
  "Acorn Mace":{"txt":"Geh zu den Demenissian Ruins am Willow River in Demeniss. Schleich dich an ein paar Banditen vorbei, die dort patrouillieren. Oben auf den Ruinen findest du die Acorn Mace.","img":"w-acorn-mace.jpg","q":"Fextralife Crimson Desert Wiki","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Acorn_Mace","reg":"Demenissian Ruins, am Willow River in Demeniss"},
  "Acria Sword":{"txt":"Reite von Hernand aus nach Nordosten zum Stellen Manor am Fluss. Die Wachen am Eingang sind blind, klettere also die Wand hoch und steig durchs Fenster ein. Löse drinnen das Klavier-Rätsel, geh durch den Geheimgang hinter dem Bücherregal in den Keller und nimm das Schwert von der Wandhalterung.","img":"w-acria-sword.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-stellen-manor-strongbox-solutions-acria-sword-location/","reg":"Hernand (nordöstlich von Drakesfall Gorge)","vor":"Klettern; Rätsellösung des Piano-Strongbox-Codes im Herrenhaus"},
  "Alabaster Curved Sword":{"txt":"Reite nordwestlich an den Rand von Forebearer's Barrens, dorthin, wo die Region an Urdavah grenzt, zur sogenannten Forgotten City - einem großen Sandkrater mit Felsring. Überquere mit dem Visione-Helm die Felsen als Trittsteine bis zur runden Plattform in der Mitte, zünde dort deine Laterne an und löse das Memory Fragment aus. Grabe danach an der leuchtenden Stelle in der Kratermitte das Schwert und einen Silberbeutel aus.","img":"w-alabaster-curved-sword.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-alabaster-curved-sword-location-stats/","reg":"Urdavah / Forebearer's Barrens (Grenze)","vor":"Visione-Helm nötig (nach Befreiung des Lioncrest Watchtower in Hernand), um das Memory Fragment am Fundort auszulösen. Ohne Helm ist die Grabstelle nicht aktivierbar."},
  "Alpha Wolf Helm":{"txt":"Geh zum Sanctum of Deliverance im Stormtalon Ridge, nördlich von Hernand. Entzünde dort die zwei Feuerschalen, damit sich ein verschlossener Raum öffnet. In der Truhe in diesem Raum liegt der Alpha Wolf Helm.","img":"a-alpha-wolf-helm.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/04/21/sanctum-of-deliverance-puzzle-walkthrough-in-crimson-desert/","reg":"Stormtalon Ridge, nördlich Hernand","vor":"Zwei Feuerschalen (Braziers) im Sanctum anzünden, um den Raum zu öffnen."},
  "Ancient Shield":{"txt":"Reise zum Sanctum of Faith am Rand von Delesyia, in der Nähe des Grey Forest im Südosten. Nutze dort die Fähigkeit Blinding Flash, um die Weinranken an einem Turm gegenüber dem Heiligtum wegzubrennen. Dahinter findest du eine Schatztruhe mit dem Ancient Shield.","img":"w-ancient-shield.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/05/10/sanctum-of-faith-puzzle-walkthrough-in-crimson-desert/","reg":"Delesyia, Sanctum of Faith","vor":"Du musst vorher Lyselia, die Witch of Humility, getroffen haben, um das Sanctum-Rätsel lösen zu können."},
  "Bismuth Spear":{"txt":"Reise nach Tashkalp, südlich von Forebearer's Barrens, zum Well of Enlightenment - einem runden Brunnen inmitten von Ruinen. Direkt daneben findest du in den Trümmern ein kleines, umschlossenes Gebäude. Darin liegt der Speer auf einem Waffenständer bereit zum Mitnehmen.","img":"w-bismuth-spear.jpg","q":"Nerdschalk","qUrl":"https://nerdschalk.com/crimson-desert-bismuth-spear-location-stats-and-effects-explained/","reg":"Tashkalp, Well of Enlightenment (südlich Forebearer's Barrens)","vor":"Das Gebiet um den Brunnen wird erst durch Story-Fortschritt erreichbar, da eine nahegelegene Blockade zunächst geräumt werden muss."},
  "Brass Rose Rapier":{"txt":"Reise in den Norden der Region Delesyia, westlich der Stadt Delesyia zur Snake Tail Wall. Dort findest du die Silverbrook Ruins mit einem kleinen Turm. Geh in den Turm hinunter ins Kellergeschoss, dort liegt die Waffe neben der Wendeltreppe.","img":"w-brass-rose-rapier.jpg","q":"nerdschalk.com","qUrl":"https://nerdschalk.com/crimson-desert-brass-rose-rapier-location-stats-and-effects-explained/","reg":"Silverbrook Ruins, nördlich City of Delesyia","vor":"Keine, die Waffe liegt frei zugänglich ohne Gegner oder Rätsel."},
  "Caliburn's Mercy Pistol":{"txt":"Geh zu Fort Musket nordöstlich von Demeniss, in der Nähe vom Valley of the Moon. Steig im Turmgebäude die Treppen bis ganz nach oben und betritt das Büro dort. Auf dem Tisch im Raum liegt die Pistole, erreichbar nur in Kapitel 1 bis 7 oder nach Abschluss der Story.","img":"w-caliburn-s-mercy-pistol.jpg","q":"VULKK.com (Fort Musket; die Pistole selbst wird auf der Seite nicht genannt)","qUrl":"https://vulkk.com/2026/05/25/how-to-get-the-dark-marksmans-armor-in-crimson-desert-overview-and-stats/","reg":"Demeniss, Fort Musket (nordöstlich von Demeniss, beim Valley of the Moon)","vor":"Kapitel 1-7 oder nach Abschluss der Hauptstory (Fort in Kap. 8-12 gesperrt)"},
  "Dagger of Dark Pursuit":{"txt":"Reite zum Sanctum of Solace südwestlich von Pailune City. Geh zum rechteckigen Wasserbecken in der Mitte und folge dem Tunnel mit den zwei Laternen. Am Ende drehst du die Steinwand mit Force Palm zur Seite, dahinter steht die Truhe.","img":"w-dagger-of-dark-pursuit.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-how-to-get-dagger-of-dark-pursuit-location/","reg":"Sanctum of Solace, südwestlich von Pailune City","vor":"Focus Palm (Höhenblick), Force Palm"},
  "Darkbringer Greatsword":{"txt":"Geh in die Bergregion im Nordwesten von Pailune, zwischen Five-Finger Mountain und Silver Wolf Mountain. Dort liegt versteckt im Nebel das White Wastes Sanctuary mit einem riesigen gefrorenen Skelett. Zieh das Schwert direkt aus dem Maul des Skeletts, ein Bosskampf ist dafür nicht nötig.","img":"w-darkbringer-greatsword.jpg","q":"powerpyx.com","qUrl":"https://www.powerpyx.com/crimson-desert-darkbringer-sword-location/","reg":"White Wastes Sanctuary, Nordwest-Pailune","vor":"Keine, von Spielbeginn an erreichbar. Das Gebiet bleibt aber oft unter Nebel und wird leicht übersehen. Alternativ Belohnung der Mission 'Archon of Antumbra' (Ator, Archon of Antumbra, Questreihe Cloister of Ruination; questlog) und Händlerin Bari (3.270 Silber)."},
  "Diverging Moon":{"txt":"Reise zum Southern Court im Süden von Demeniss. Du musst weder ins Gebäude hinein noch einen Boss besiegen. Die Waffe liegt draußen im Zeltbereich links vom Eingang.","img":"w-diverging-moon.jpg","q":"Nerdschalk","qUrl":"https://nerdschalk.com/crimson-desert-diverging-moon-location-stats-and-crescent-moon-slash-abyss-gear-ability-explained/","reg":"Southern Court, Demeniss"},
  "Divine Echoes Bow":{"txt":"Reise zu den Rockshard Valley Ruins, einem von Gegnern bewachten Lager. Kämpfen musst du nicht. Gleite von oben direkt zur Truhe im Lager und nimm den Bogen.","img":"w-divine-echoes-bow.jpg","q":"Nerdschalk","qUrl":"https://nerdschalk.com/crimson-desert-divine-echoes-bow-location-stats-and-effects-rockshard-valley-ruins-camp-guide/","reg":"Crimson Desert Region, Rockshard Valley Ruins (nahe Tashkalp)","warn":"Die Anreise zu den Rockshard Valley Ruins wird in den Quellen unterschiedlich beschrieben. Der Ortsname stimmt, die Route nicht sicher."},
  "Fallen Kingdom's Rapier":{"txt":"Geh zu den Icemoor Castle Ruins im Westen von Hernand, hinter den Thron des Stag Lord. Folge Treppe und Brücke bis zur Sackgasse mit dem Loch in der Wand und schlag die Bretter davor ein. Im Raum dahinter steht eine Truhe, das Rapier lehnt links daneben am Fass.","img":"w-fallen-kingdom-s-rapier.jpg","q":"Nerdschalk / GameRant","qUrl":"https://nerdschalk.com/crimson-desert-fallen-kingdoms-rapier-location-unlock-and-stats-explained/","reg":"Icemoor Castle Ruins, westliches Hernand","vor":"Force Palm; nur von Damiane nutzbar","warn":"Ob für die Bretter zwingend Force Palm nötig ist, ist nicht belegt."},
  "Frostcursed Plate Armor":{"txt":"Geh zur Mistshard Cave, einer Wasserfallhöhle an der Grenze zwischen Demeniss und Pailune beim Deadfire Mountain. Nutze den Stab-Stoß, um unbeschadet durch den Wasserfall zu kommen. Brich dahinter die Felswand mit Force Palm auf, dort steht die Truhe.","img":"a-frostcursed-plate-armor.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-frostcursed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Grenzgebiet Demeniss/Pailune nahe Deadfire Mountain, laut Ingame-Beschreibung in den 'Smoking Lands'","vor":"Kein Quest nötig, frei zugänglicher Weltfund. Skills Stab und Force Palm nötig (beide früh im Spiel verfügbar). Die Rüstung selbst ist laut VULKK nicht aufwertbar, craftbar seit Patch 1.13.00 laut Wiki nicht separat verifiziert.","warn":"Anders als die übrigen Teile des Sets liegt die Rüstung nicht in den Grotten am Denn River, sondern in der Mistshard Cave im Osten."},
  "Frostcursed Plate Boots":{"txt":"Geh nördlich von Demeniss zum Denn River und folge ihm stromaufwärts bis zu einem Wasserfall, der Well of Tragedy Grotto (nordwestlich von Tariv). Nutze am Wasserfall den Stab-Stoß, um die versteckte Höhle dahinter zu betreten. Darin steht die Truhe mit den Frostcursed Plate Boots.","img":"a-frostcursed-plate-boots.jpg","q":"vulkk.com, gamerant.com, game8.co","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-frostcursed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Demeniss (nördlich, Denn River)","vor":"Stab-Stoß"},
  "Frostcursed Plate Gloves":{"txt":"Geh zur Lunar Spirit Grotto, einer Höhle hinter einem Wasserfall am Denn River in Demeniss, westlich von Tariv. Nutze den Stab-Stoß, um durch den Wasserfall zu gelangen. In der Höhle dahinter liegt die Truhe mit den Handschuhen.","img":"a-frostcursed-plate-gloves.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-frostcursed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Lunar Spirit Grotto, Demeniss (westlich Tariv)","vor":"Stab-Stoß, um durch den Wasserfall zu gelangen."},
  "Frostcursed Plate Helm":{"txt":"Geh zu den Chattering Rocks im Nordwesten von Demeniss, im Gebiet der Tariv-Zauberer. Suche an einem Steingebäude mit Außenleiter eine Wand voller grüner Ranken. Verbrenne die Ranken mit einer Feuerfähigkeit, dahinter liegt die Truhe mit dem Helm.","img":"a-frostcursed-plate-helm.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-frostcursed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Chattering Rocks, Nordwest-Demeniss","vor":"Feuerfähigkeit (z.B. Blinding Flash), um die Ranken zu verbrennen."},
  "Frozen Anguish":{"txt":"Reite zum Spire of Frost, östlich von Beighen an der Grenze zwischen Pailune und Demeniss. Löse die vereiste Säule links der Treppe mit Turning Slash und entzünde sie, damit sich die Tür öffnet. Direkt unter der Wendeltreppe im Turm steht die Truhe mit dem Frozen Anguish.","img":"w-frozen-anguish.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/04/18/spire-of-frost-walkthrough-in-crimson-desert/","reg":"Spire of Frost, Grenze Pailune/Demeniss östlich von Beighen","vor":"Turning Slash (Skill)"},
  "Frozen Soul":{"txt":"Geh in die Region Skoghorn in den Argent Peaks im Westen von Pailune. Dort liegt eine Grube, umgeben von Felsen und zerbrochenen Holzbalken. Am Boden der Grube liegt ein Skelett, direkt daneben liegt das Frozen Soul zum Aufsammeln.","img":"w-frozen-soul.jpg","q":"Nerdschalk","qUrl":"https://nerdschalk.com/crimson-desert-frozen-soul-weapon-location-stats-and-effects-skoghorn-location-guide/","reg":"Skoghorn, The Argent Peaks (Pailune)"},
  "Goblin King's Treasure":{"txt":"Reite zur Mudridge Cabin im Pororin Forest, nördlich von Pororin Village. Besiege die Banditen und klettere am kleineren Gebäude zur Plattform über dem Sumpf hinunter. Kriech durch die kleine Öffnung, am Ende des Gangs steht die Truhe.","img":"w-goblin-king-s-treasure.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-how-to-get-goblin-kings-treasure-dagger-location/","reg":"Mudridge Cabin, Pororin Forest"},
  "Golden Greed Plate Armor":{"txt":"Geh zu den Bursada Castle Ruins im Dschungel zwischen Wüste und Delesyia. Betritt das große Tor am Fuß der Burg und folge dem Gang nach links bis zum Ende. Schlag dort die brüchige Wand mit Force Palm ein, dahinter steht die Truhe.","img":"a-golden-greed-plate-armor.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/05/07/how-to-get-the-golden-greed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Tashkalp / Grenze Krimsonwüste-Delesyia, Bursada Castle Ruins"},
  "Golden Greed Plate Boots":{"txt":"Geh zur Arehaza Cave am Red River, nordwestlich der Bursada Castle Ruins im Dschungel zwischen Delesyia und der Crimson Desert. Der Eingang ist mit einer Bismuth-Wand blockiert, die du mit Focus: Force Palm zerstörst. Dahinter liegt die Truhe mit den Golden Greed Plate Boots.","img":"a-golden-greed-plate-boots.jpg","q":"vulkk.com, allthings.how","qUrl":"https://vulkk.com/2026/05/07/how-to-get-the-golden-greed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Grenzgebiet Delesyia/Crimson Desert (Red River)","vor":"Focus: Force Palm-Fähigkeit"},
  "Golden Greed Plate Cloak":{"txt":"Folge dem Red River flussaufwärts nach Norden, bis du an einen Wasserfall kommst. Das ist der Eingang zur Venomblade Grotto, versteckt hinter den Wassermassen. Nutze den Stab-Stoß, um durch den Wasserfall in die Höhle zu gelangen, dort liegt die Truhe mit dem Golden Greed Plate Cloak.","img":"a-golden-greed-plate-cloak.jpg","q":"vulkk.com","qUrl":"https://vulkk.com/2026/05/07/how-to-get-the-golden-greed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Red River / Venomblade Grotto","vor":"Fähigkeit 'Stab' (Stoß-Angriff), um durch den Wasserfall zu tauchen."},
  "Golden Greed Plate Gloves":{"txt":"Geh zur Holzbrücke östlich vom Drywind Valley, wo der Denn River einen Wasserfall bildet. Auf halber Höhe liegt ein schmaler Felsvorsprung. Stoß von dort mit dem Stab durch den Wasserfall in die Höhle, ganz hinten steht die Truhe.","img":"a-golden-greed-plate-gloves.jpg","q":"vulkk.com, gamerant.com","qUrl":"https://vulkk.com/2026/05/07/how-to-get-the-golden-greed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Delesyia, Gale of Judgement Cave (Drywind Valley, Denn River)","vor":"Stab-Stoß (Standard bei allen drei Charakteren)"},
  "Golden Greed Plate Helm":{"txt":"Geh zum Sanctum of Renunciation am Red River, im Dschungel zwischen Delesyia und der Crimson-Wüste. Entzünde die zwei Fackeln neben der Treppe an der Südwestseite des Gebäudes. Dahinter öffnet sich eine geheime Wand mit der Truhe.","img":"a-golden-greed-plate-helm.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/05/07/how-to-get-the-golden-greed-plate-armor-in-crimson-desert-overview-and-stats/","reg":"Sanctum of Renunciation","vor":"Zwei Fackeln/Laternen an der Treppe anzünden."},
  "Grasping Moon":{"txt":"Reise zum Western Court in Demeniss. Die Waffe liegt im weißen Zelt auf einem Waffenständer und lässt sich dort auch ohne Bosskampf mitnehmen.","reg":"Western Court, Demeniss","warn":"Ob der Western Court schon vor Kapitel 8 betretbar ist, ist nicht belegt. Vor Kapitel 8 kommt ihr eventuell nicht heran."},
  "Helm of Ignition":{"txt":"Geh zum Torchlight Beacon, einem Leuchtturm auf einem Hügel westlich von Hernand Town. Folge der geschwungenen Straße bergauf bis zu den Zelten am Fuß des Turms. In einem der Zelte liegt der Helm einfach zum Mitnehmen bereit.","img":"a-helm-of-ignition.jpg","q":"Nerdschalk","qUrl":"https://nerdschalk.com/crimson-desert-how-to-find-helm-of-ignition-torchlight-beacon-location-stats-and-activation-guide/","reg":"Torchlight Beacon, westlich Hernand","vor":"Keine - freies Aufsammeln, kein Kampf nötig."},
  "Hollow Visage":{"txt":"Geh zum Wasserfall am Mountain of Frozen Souls im südlichen Hernand. Stell dich vor den Wasserfall und nutze den Stab-Stoß, um hindurchzustoßen, dahinter öffnet sich die Dawn Cave. Folge der Höhle bis zum Ende, dort steht die Truhe mit der Waffe.","img":"w-hollow-visage.jpg","q":"gamerant.com","qUrl":"https://gamerant.com/crimson-desert-how-get-reed-devil-armor-sword-hollow-visage-location/","reg":"Dawn Cave, Mountain of Frozen Souls, Südliches Hernand","vor":"Stab-Stoß muss freigeschaltet sein, um durch den Wasserfall zu gelangen."},
  "Hwando":{"txt":"Das Lioncrest Manor liegt im Nordwesten von Hernand, gleich bei Hernand Castle. Klettere an der Westseite des Nebengebäudes durch das Fenster ohne Glas hinein. Dahinter liegt ein verschlossener Raum, für den du einen Schlüssel brauchst, dort steht die Truhe.","reg":"Lioncrest Manor (Nebengebäude), Hernand","q":"Fextralife Crimson Desert Wiki","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Hwando","vor":"Ein Schlüssel wird benötigt (laut bisheriger Angabe z.B. für 30 Bronzemünzen bei Grimrack in Hernand Farmhouse kaufbar, oder von Banditen erbeutbar; questlog führt den Gegenstand 'Key' mit 15 Kupfer bei mehreren Händlern, u. a. Grimrak — Währungseinheit der Altangabe ungeklärt). Der Schlüssel selbst steht nicht auf der Fextralife-Seite. questlog führt die Waffe außerdem bei den Händlern Rhett und Lederson (2.289 Silber), Fextralife nennt sie nicht kaufbar."},
  "Leather Armor of the Fallen Kingdom":{"txt":"Geh zur Frozen Soul Cave in Everfrost, südlich vom Sanctum of Benediction (auf der Karte zwischen den Buchstaben E und R von 'Hernand'). Folge dem Fluss nach Westen bis du auf einen Wasserfall triffst und tritt mit dem Stab-Stoß hindurch. In der kleinen Höhle dahinter steht die Truhe mit der Rüstung.","img":"a-leather-armor-of-the-fallen-kingdom.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/03/31/how-to-get-the-fallen-kingdom-armor-in-crimson-desert-overview-and-stats/","reg":"Everfrost / West-Hernand","vor":"Stab-Stoß (Waffenskill), um durch den Wasserfall zu gelangen."},
  "Leather Helm of the Fallen Kingdom":{"txt":"Geh zum Sanctum of Benediction im Westen von Hernand. Zünde dort die Fackel neben der Treppe an, dann öffnet sich eine geheime Tür in der Wand. Dahinter findest du die Truhe mit dem Helm.","img":"a-leather-helm-of-the-fallen-kingdom.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/03/31/how-to-get-the-fallen-kingdom-armor-in-crimson-desert-overview-and-stats/","reg":"Sanctum of Benediction, West-Hernand","vor":"Fackel/Laterne neben der Treppe anzünden."},
  "Light of the Battlefield Plate Gloves":{"txt":"Geh in den Südbezirk von Varnia. Dort gibt es eine Kante mit zwei Bettlern, über die du dich hochziehen kannst. Schau von unten nach Süden, dann siehst du ein halb geschlossenes Tor; kriech hindurch zur Truhe mit den Light of the Battlefield Plate Gloves.","img":"a-light-of-the-battlefield-plate-gloves.jpg","q":"vulkk.com, gamerant.com","qUrl":"https://vulkk.com/2026/06/12/how-to-get-damianes-light-of-the-battlefield-armor-in-crimson-desert-overview-and-stats/","reg":"Varnia (Südbezirk)"},
  "Light of the Battlefield Plate Helm":{"txt":"Geh zur Halbinsel in Trivana Sound, nordöstlich vom Outlaw Canyon an der Straße nach Varnia. Klettere unter den großen Felsen dort und schau nach Norden. Mitten unter dem Felsen steht die Truhe mit dem Helm.","img":"a-light-of-the-battlefield-plate-helm.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/06/12/how-to-get-damianes-light-of-the-battlefield-armor-in-crimson-desert-overview-and-stats/","reg":"Trivana Sound, nordöstlich Outlaw Canyon","vor":"Unter den Felsen klettern (Kletterfähigkeit)."},
  "Lightning Spear":{"txt":"Reite nördlich von Pailune-Stadt am Upper Denn River entlang, vorbei an einem kleinen Fischerdorf, bis du auf höherem Gelände bei einem großen Baum den Black Wall Bandit Camp erreichst. Das Lager liegt am Zusammenfluss zweier Flussarme am Rand der Black-Wall-Region. Dort liegt der Speer auf einem Waffenregal bereit zum Mitnehmen.","img":"w-lightning-spear.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-how-get-craft-kuku-lightning-spear-location/","reg":"Pailune, Black Wall Bandit Camp (nördlich der Stadt)"},
  "Mace of Ambition":{"txt":"Geh zum Spire of Clockwork bei Breezeblown Knoll im Osten von Demeniss. Den Schlüssel dafür bekommst du erst nach Kapitel 8 der Hauptstory. Seit Patch 1.15 liegt die Keule auf einem Holzsteg im Raum mit der Drehtür, einige Stockwerke unter der Turmspitze.","reg":"Demeniss, Spire of Clockwork bei Breezeblown Knoll","vor":"Hauptquest Kapitel 8 (A Fleeting Dream) abgeschlossen für den Spire-Schlüssel. Abweichung: Die Fextralife-Seite beschreibt den Raum noch als nur per Glitch erreichbar (Patch 1.15.00 laut Pearl-Abyss-Patchnotes ändert das; ob die Seite nachgeführt wird, ist ungeklärt). questlog führt die Keule zusätzlich beim Händler Brek (1.064 Silber)."},
  "Odeck's Protector Plate Armor":{"txt":"Reise in den Nordwesten von Pailune zu den Wayward Woods am Silver Wolf Mountain. Suche im nebligen Gebiet nach einem der vier Pits, die als Löcher im Boden liegen, und folge den Rinnen zum versperrten Schacht. Zerstöre die glänzende Bismuth-Wand mit Focused Force Palm, steig hinab und öffne die Truhe mit dem Brustpanzer.","img":"a-odeck-s-protector-plate-armor.jpg","q":"VULKK","qUrl":"https://vulkk.com/2026/05/22/how-to-get-the-odecks-protector-plate-armor-and-defeat-the-forgotten-general-in-crimson-desert/","reg":"The Four Pits of Wayward Woods, Nordwest-Pailune","vor":"Focused Force Palm. Alternativ Belohnung der Mission 'Fight the slumbering guardian deity of the Odeck Ruins' (Quest 'Slumbering Soul', Boss The Forgotten General; questlog)."},
  "Odeck's Protector Plate Boots":{"txt":"Reise nach Südost-Hernand zum Sanctum of Temperance, südöstlich von Howling Hill. Geh an der Nordostseite des Eingangs die Treppe hinauf und klettere durch die fensterartige Öffnung in der Wand. Suche dahinter die zweite, von Büschen oder Ranken verdeckte Öffnung; geh hindurch oder verbrenne die Pflanzen, falls sie den Weg blockieren, und öffne die Truhe.","img":"a-odeck-s-protector-plate-boots.jpg","q":"VULKK","qUrl":"https://vulkk.com/2026/05/22/how-to-get-the-odecks-protector-plate-armor-and-defeat-the-forgotten-general-in-crimson-desert/","reg":"Sanctum of Temperance, Südost-Hernand","vor":"Keine sicher bestätigte Voraussetzung; Blinding Flash oder ein Feuerangriff kann zum Abbrennen der Ranken nötig sein. Alternativ Belohnung der Mission 'Fight the slumbering guardian deity of the Odeck Ruins' (Quest 'Slumbering Soul', Boss The Forgotten General; questlog).","warn":"Ob die Pflanzen vor der zweiten Öffnung abgebrannt werden müssen oder einfach durchquerbar sind, sagen die Quellen unterschiedlich. Nehmt Feuer mit, falls sie den Weg blockieren."},
  "Odeck's Protector Plate Cloak":{"txt":"Reise zum Silver Wolf Mountain, wo die Frostwind Cave nahe dem Osttor von Pailune liegt. Geh nicht in den offensichtlichen Höhleneingang, sondern suche zwischen Brücke und Wachturm den Spalt mit der Leiter; rote Palisaden und ein kaputter Wagen dienen als Orientierung. Folge dem von Bären besetzten Gang bis zur großen Kammer, halte dich links und steig durch das kleine Loch hinab, wo der Umhang lose am Boden liegt.","img":"a-odeck-s-protector-plate-cloak.jpg","q":"VULKK","qUrl":"https://vulkk.com/2026/05/22/how-to-get-the-odecks-protector-plate-armor-and-defeat-the-forgotten-general-in-crimson-desert/","reg":"Frostwind Cave, Silver Wolf Mountain bei Pailune","vor":"Keine; im Versteck warten zahlreiche Black-Bear-Gegner. Alternativ Belohnung der Mission 'Fight the slumbering guardian deity of the Odeck Ruins' (Quest 'Slumbering Soul', Boss The Forgotten General; questlog).","warn":"Andere Guides nennen diesen Ort 'Blackbear's Hideout' statt Frostwind Cave. Gemeint ist derselbe Höhlenkomplex, ihr sucht also nicht zwei verschiedene Stellen."},
  "Odeck's Protector Plate Gloves":{"txt":"Reise in West-Zentral-Hernand durch die Witchwoods zum Perwin Quarry. Suche am Nordrand des Steinbruchs in der Felswand nach einer kleinen Höhle, deren Eingang mit einer glänzenden Bismuth-Wand verschlossen ist. Zerstöre die Wand mit Focused Force Palm, versiegle die Abyss Cells und öffne hinten die Truhe mit den Handschuhen.","img":"a-odeck-s-protector-plate-gloves.jpg","q":"VULKK","qUrl":"https://vulkk.com/2026/05/22/how-to-get-the-odecks-protector-plate-armor-and-defeat-the-forgotten-general-in-crimson-desert/","reg":"Perwin Quarry, West-Zentral-Hernand","vor":"Focused Force Palm; Axiom Force für die Abyss Cells in der Höhle. Alternativ Belohnung der Mission 'Fight the slumbering guardian deity of the Odeck Ruins' (Quest 'Slumbering Soul', Boss The Forgotten General; questlog)."},
  "Odeck's Protector Plate Helm":{"txt":"Geh nach Nordost-Demeniss zu Hollow Haven, südwestlich von Hexe Sanctuary und nahe dem Denn River. Suche an der Felswand nach dem mit Bismuth versiegelten Höhleneingang und zerstöre die glänzende Wand mit Focused Force Palm. Versiegle die Abyss Cells mit Axiom Force und folge der Höhle bis zur Truhe mit dem Helm.","img":"a-odeck-s-protector-plate-helm.jpg","q":"VULKK","qUrl":"https://vulkk.com/2026/05/22/how-to-get-the-odecks-protector-plate-armor-and-defeat-the-forgotten-general-in-crimson-desert/","reg":"Hollow Haven, Nordost-Demeniss","vor":"Focused Force Palm; Axiom Force für die Abyss Cells in der Höhle. Alternativ Belohnung der Mission 'Fight the slumbering guardian deity of the Odeck Ruins' (Quest 'Slumbering Soul', Boss The Forgotten General; questlog)."},
  "Plate Armor of the Shadows":{"txt":"Geh zum Everfrost Watchtower in den Argent Peaks, nördlich der Hoenmark Ruins im Westen von Hernand. An der Südseite des Turms findest du eine verriegelte Tür in der Felswand mit einer Laterne daneben. Entzünde die Laterne, das Tor öffnet sich und in der Truhe dahinter liegt die Rüstung.","img":"a-plate-armor-of-the-shadows.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-plate-armor-of-the-shadows-saurons-set-in-crimson-desert-overview-and-stats/","reg":"Argent Peaks, West-Hernand","vor":"Kein Quest nötig, frei zugänglicher Weltfund. Vorsicht vor Bleed Bandits im Turmbereich. questlog führt die Rüstung zusätzlich als Belohnung der Mission 'Obtain Beloth, the Darksworn's loot' (Quest 'White Blizzard'); game8 nennt Beloth als Drop aller fünf Shadows-Teile."},
  "Plate Boots of the Shadows":{"txt":"Die Frostclaw Cave liegt hinter einem Wasserfall am Nas River im Süden von Hernand, dort wo der Fluss in Richtung Everfrost läuft. Stoß mit dem Stab durch den Wasserfall in die Höhle. Ganz hinten steht die Truhe.","img":"a-plate-boots-of-the-shadows.jpg","q":"vulkk.com, pcgamer.com","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-plate-armor-of-the-shadows-saurons-set-in-crimson-desert-overview-and-stats/","reg":"Hernand (Westen, Frostclaw)","vor":"Stab-Stoß","warn":"Zur genauen Lage der Höhle widersprechen sich die Quellen. Haltet euch an die Karte, der Wasserfall ist der sichere Anhaltspunkt."},
  "Plate Cloak of the Shadows":{"txt":"Geh zu den Hoenmark Ruins nördlich von Hernand, wo ständig ein Schneesturm tobt. Etwas westlich der Ruinen steht ein Steinhaus, auf dessen Dach eine auffällige Steinplatte liegt. Ducke dich davor und schlag sie mit Force Palm ein, darunter wartet die Truhe.","img":"a-plate-cloak-of-the-shadows.jpg","q":"thegamer.com","qUrl":"https://www.thegamer.com/crimson-desert-armor-of-shadows-set-guide-map-location-beloth/","reg":"Everfrost / Hoenmark Ruins","vor":"Fähigkeit 'Force Palm', um die Steinplatte auf dem Dach einzuschlagen; Kälte-/Eisresistenz oder Vorrat an Essen wegen des Schneesturms empfohlen."},
  "Plate Gloves of the Shadows":{"txt":"Geh an den Westrand von Hernand, etwas südlich des Flusses, der in die Everfrost-Berge fließt. Dort liegt die Everfrost Cave hinter einem Wasserfall, tief im Schnee. Ganz hinten in der Höhle steht die Truhe.","img":"a-plate-gloves-of-the-shadows.jpg","q":"vulkk.com","qUrl":"https://vulkk.com/2026/04/26/how-to-get-the-plate-armor-of-the-shadows-saurons-set-in-crimson-desert-overview-and-stats/","reg":"Hernand (Westen, Everfrost)"},
  "Propeller Spear":{"txt":"Reise zur Aeronautical Research Base im Südosten von Delesyia, direkt an der Küste. Suche unter den Wächtertürmen der Anlage denjenigen, aus dessen Schornstein Rauch aufsteigt, und steige darin die Treppe hoch bis in einen Raum voller Kanonen und Kanonenkugeln. Der Speer hängt dort an einem Waffenregal neben einem Pfeiler.","img":"w-propeller-spear.jpg","q":"Destructoid","qUrl":"https://www.destructoid.com/how-to-get-propeller-spear-in-crimson-desert/","reg":"Delesyia, Aeronautical Research Base (Südosten)"},
  "Rhonid Large Shield":{"txt":"Reite nordwestlich von Hernand Town zum Lioncrest Manor und besorg dir vorher einen Schlüssel oder eine Maske beim Hinterhof-Händler. Klettere an der rechten Seite des Herrenhauses durchs Fenster ein, geh durch die große Halle und über den Innenbalkon im Obergeschoss. Hinter der abgeschlossenen Tür auf dem Balkon steht die Truhe mit dem Rhonid Large Shield.","img":"w-rhonid-large-shield.jpg","q":"Fextralife Crimson Desert Wiki / GameRant","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Rhonid_Large_Shield","reg":"Lioncrest Manor, nordwestlich von Hernand Town","vor":"Schlüssel oder Maske (zum Diebstahl eines Schlüssels) nötig für die verschlossene Tür"},
  "Righteous Verdict":{"txt":"Reite zum Nightfell Expedition Camp im Süden von Demeniss, nahe der Küste östlich der Steel Mountains. Von dort führt eine Höhle hinab in die Demeniss Ancestors' Ruins. Spring über die großen Steinsäulen im Wasser und geh durch die Tür am Ende - im letzten Raum steckt das Righteous Verdict im Boden.","img":"w-righteous-verdict.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-righteous-verdict-sword-location/","reg":"Demeniss Ancestors' Ruins, südliches Demeniss","vor":"Springen/Klettern über Steinsäulen"},
  "Ring of the Earth":{"txt":"Geh zu den Reedfield Graves, einem Friedhof in den Hernand Highlands südlich von Hernand Castle. Dort steht das Haus, an dem du im Kapitel-3-Auftrag 'Nonhuman' zum ersten Mal auf den Reed Devil getroffen bist. Auf einem der Gräber rechts von diesem Haus liegt der Ring of the Earth.","img":"w-ring-of-the-earth.jpg","q":"Fextralife Crimson Desert Wiki","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Ring_of_the_Earth","reg":"Reedfield Graves, Hernand Highlands (südlich von Hernand Castle)"},
  "Scorchflame Plate Armor":{"txt":"Geh zum Golden Trading Post nördlich von Demeniss. Im westlichen Bereich zwischen zwei Holztreppen findest du eine schmale Holzwand, durch die du dich duckend hindurchzwängst. Dahinter steht die Truhe mit der Scorchflame Plate Armor.","img":"a-scorchflame-plate-armor.jpg","q":"GameRant","qUrl":"https://gamerant.com/crimson-desert-scorchflame-knight-armor-full-set-locations/","reg":"Demeniss, Golden Trading Post (laut GameRant auf der Karte zwischen den Buchstaben „D“ und „E“ von „Demeniss“)","vor":"Kein Quest nötig, frei zugänglicher Weltfund. Craftbar über das Hexen-Rezept 'Scorchflame Plate Armor' (Blueprint bei Hexe Lyselia, 500 Silber; Material 3x Flameward III, 3x Abyss Cell, 2x Platinum, 10x Garnet; questlog)."},
  "Scorchflame Plate Gloves":{"txt":"Reise ins Grenzgebiet zwischen Hernand und Demeniss zur Twilight Grotto, nördlich von Rocca's Hill am Denn River. Nutze vor dem zweiten Wasserfall die Stich-Fähigkeit (R1+Dreieck), um ohne Rückstoß durch das Wasser zu gelangen. Dahinter liegt eine kleine Grotte mit einer Truhe, in der die Scorchflame Plate Gloves liegen.","img":"a-scorchflame-plate-gloves.jpg","q":"Fextralife","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Scorchflame_Plate_Gloves","reg":"Hernand/Demeniss-Grenze, Twilight Grotto (nördlich Rocca's Hill)"},
  "Scorchflame Plate Helm":{"txt":"Reise zur Stonewell Farm an der Grenze zwischen Demeniss und Hernand. Suche auf dem Hof nach dem hohen Lagerturm und klettere ins obere Stockwerk. Die Truhe steht neben einem Loch im Boden, nähere dich also vorsichtig.","img":"a-scorchflame-plate-helm.jpg","q":"Crimson Desert Wiki (Fextralife)","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Scorchflame_Plate_Helm","reg":"Stonewell Farm, Grenze Demeniss/Hernand","vor":"Keine zwingende Quest nötig; die Farm kann während der Hauptquest 'Traitor' durch Bastiers Inquisitoren blockiert sein, die Truhe ist aber auch ohne Quest-Abschluss erreichbar","warn":"Farm, Turm und Truhe sind belegt, die Angaben zur Hofseite und zum Stockwerk widersprechen sich in den Quellen. Ob der Helm an Kliff gebunden ist, ist ebenfalls unbestätigt."},
  "Shield of Conviction":{"txt":"Geh zur Church of Calphade nordwestlich von Hernand, nahe dem Deepfog Basin. Klettere am Turm hoch bis zu einem kaputten Fenster direkt unter der Glocke, zum Beispiel mit Force Palm. Im Turm steht die Truhe mit dem Schild und einer Palmar Pill.","img":"w-shield-of-conviction.jpg","q":"Nerdschalk","qUrl":"https://nerdschalk.com/crimson-desert-shield-of-conviction-location-guide-calphade-church-treasure-chest-and-how-to-get-there/","reg":"Hernand, Church of Calphade (nordwestlich von Hernand, nahe Deepfog Basin)","vor":"keine besondere, früh im Spiel erreichbar"},
  "Shield of Radiance":{"txt":"Geh an den östlichen Rand der Karte, südlich von Trader's Expanse. Dort klafft ein großes Loch im Boden, eher eine Grube. Steig hinein, der Schild liegt offen darin, ganz ohne Truhe.","img":"w-shield-of-radiance.jpg","q":"VULKK.com","qUrl":"https://vulkk.com/2026/06/12/how-to-get-damianes-light-of-the-battlefield-armor-in-crimson-desert-overview-and-stats/","reg":"Östlich der Karte, südlich von Trader's Expanse"},
  "Shield of Ringing":{"txt":"Geh zum Laughing Marionette Zirkus außerhalb der Demenissian-Hauptstadt. Betritt das rot-weiße Zelt dort. Der Shield of Ringing liegt neben einem Harlekin auf einem Tisch im Zelt.","reg":"Demenissian-Hauptstadtregion, The Laughing Marionette","q":"Fextralife Crimson Desert Wiki","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Shield_of_Ringing"},
  "Soul Spear":{"txt":"Schau auf der Weltkarte direkt über dem 'H' von Hernand: dort liegt in den Argent Peaks ein versteckter Dungeon, die Antumbra Ritual Grounds. Der Eingang liegt an einer Felswand; geh von dort zwei Ebenen nach unten. Auf einer Plattform in der Mitte des unteren Raums schwebt die Soul Spear.","img":"w-soul-spear.jpg","q":"Fextralife Crimson Desert Wiki","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Soul_Spear","reg":"Antumbra Ritual Grounds / Tomb of Frozen Souls, Argent Peaks, nordwestlich von Hernand"},
  "Sunset Reed Leather Armor":{"txt":"Reise in den Süden von Hernand zum Mountain of Frozen Souls. Suche an der Ostseite des Berges die Echoing Waves Cave hinter einem Wasserfall. Stoß mit dem Stab durch den Wasserfall und öffne die Truhe in der Höhle.","img":"a-sunset-reed-leather-armor.jpg","q":"Crimson Desert Wiki (Fextralife)","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Sunset_Reed_Leather_Armor","reg":"Mountain of Frozen Souls (Ostseite), Süd-Hernand","vor":"Keine, frei zugänglich sobald man die Höhle findet"},
  "Survivor's Solitude":{"txt":"Geh westlich des Scholastone Institute durch The Witchwoods bis zu einem Fluss, dem du nach Norden folgst. Am Ende des Flusses liegt ein großer Wasserfall. Stell dich davor und nutze den Stab-Stoß, um hindurchzustoßen, dahinter liegt die Death's Grip Cavern mit der Truhe.","img":"w-survivor-s-solitude.jpg","q":"method.gg","qUrl":"https://www.method.gg/crimson-desert/crimson-desert-survivors-solitude-weapon-location-best-early-game-sword","reg":"Death's Grip Cavern, westlich Scholastone Institute / The Witchwoods","vor":"Stab-Stoß nötig, um durch den Wasserfall zu gelangen. Von Spielbeginn an erreichbar."},
  "Troll Hook Greataxe":{"txt":"Geh zur Vinewood Winery in Demeniss, erkennbar an einem auffälligen weißen Silo. Betritt den Silo von unten und klettere mit einer Kletter-Fähigkeit nach oben zum Dach. Oben findest du die Truhe mit der Axt.","reg":"Demeniss, Vinewood Winery"},
  "Visione Helm":{"txt":"Steig auf den Lioncrest Watchtower westlich von Hernand, dafür musst du den Rankenbewuchs am Turmfuß mit einem brennenden Pfeil abfackeln. Kämpfe dich an der Spitze durch Banditen und pass unterwegs auf Sägeblatt-Fallen auf, die durch Stolperdrähte ausgelöst werden. Oben liegt der Visione Helm auf dem Boden neben einem Fass in der Nähe des Altars.","reg":"West-Hernand, Lioncrest Watchtower","q":"Fextralife Crimson Desert Wiki (Seite „Visione“)","qUrl":"https://crimsondesertgame.wiki.fextralife.com/Visione","vor":"Teil der Hauptquest 'Unexpected Gift' in Kapitel 2 (Questschritte 'Where the Light Leads' und 'Reunion'). Der Helm wird zwangsläufig beim Story-Fortschritt gefunden, kein rein optionaler Weltfund.","warn":"Kein freier Fund: der Helm gehört zur Hauptquest 'Unexpected Gift' in Kapitel 2. Vorher kommt ihr nicht heran."},
  "Vow of the Dead King":{"txt":"Nimm die Straße südwestlich von Pailune City, die am Sanctum of Solace vorbeiführt, und folge ihr bergauf bis zu den Frostveiled Castle Ruins auf dem Silver Wolf Mountain. Steig in die Ruinen hinab in den Keller, geh durch den Feuer-Korridor und zünde die Kerze an, um eine Tür zu öffnen. Dahinter liegt die Waffe auf einem Steinsarg bzw. Steintisch.","img":"w-vow-of-the-dead-king.jpg","q":"gamerant.com","qUrl":"https://gamerant.com/crimson-desert-vow-of-the-dead-king-location/","reg":"Frostveiled Castle Ruins, Silver Wolf Mountain, Nord-Pailune","vor":"Keine besondere Voraussetzung genannt, Gebiet ist von Banditen bewacht."}
};
